//! hand is a silent-corruption source (a wrong bit turns a success check into a
//! failure path with no compile error). `verify_constants.py` re-checks these
//! against the header in `vibeos-cli check`.
//!
//! HRESULT is a SIGNED 32-bit value (FAILED(hr) is `hr < 0`), so each is emitted
//! as `i32` via a wrapping cast from the header's unsigned literal.
